rules:
- id: "vuln-gitlab-oauth-plugin-695ce63f"
  pattern: |
    import sun.net.util.URLUtil;
    ...
    HttpSession session = request.getSession(false);
    if (session != null) {
        // avoid session fixation
        session.invalidate();
    }
    request.getSession(true);
  pattern-not: |
    import javax.servlet.http.HttpSession;
    ...
    HttpSession session = request.getSession(false);
    if (session != null) {
        // avoid session fixation
        session.invalidate();
    }
    request.getSession(true);
  languages: ["java"]
  message: "Potential vulnerability in GitLab OAuth plugin detected. Avoid using sun.net.util.URLUtil and instead use javax.servlet.http.HttpSession."
  severity: ERROR
  metadata:
    source-url: github.com/jenkinsci/gitlab-oauth-plugin/commit/695ce63fddb3567cf8d87339ddc1fa3b67ae2db8
    category: security
    cwe: CWE-20
    owasp: A3
